 ('NAT-01','Android','App detects the Android bridge',"(()=>T.ok(!!nat,'nat present'))()"),
 ('NAT-02','Android','Saving a habit with a reminder schedules it on the phone',"(async()=>{__calls.length=0;openEdit(null);"+W+"T.set('#fName','Native Remind');const m=T.q('#habitMoreBtn');m&&m.click();await T.w(200);const a=T.q('#btnAddTime');a&&a.click();await T.w(200);const t=T.q('#remList input[type=time]');if(t){t.value='06:45';t.dispatchEvent(new Event('change',{bubbles:true}));}T.click('#saveBtn');await T.w(1600);const sched=__calls.filter(c=>/schedul|alarm|remind/i.test(c[0]));return T.ok(sched.length>0,'bridge calls: '+[...new Set(__calls.map(c=>c[0]))].join(','))})()"),
 ('NAT-03','Android','Changes are saved to the phone copy for widgets',"(async()=>{__calls.length=0;setMood(today(),2);persist({now:true});await T.w(1500);const s=__calls.find(c=>/saveState/i.test(c[0]));return T.ok(!!s,s?'saveState called':'no saveState')})()"),
 ('NAT-04','Android','Messages go to the native toast (never \"null\")',"(()=>{__calls.length=0;toastN(null);toastN('');toastN('Hello');const t=__calls.filter(c=>c[0]==='toast');return T.ok(t.length===1&&t[0][1][0]==='Hello',JSON.stringify(t))})()"),
 ('NAT-05','Android','Quick-log widget Journal link opens a new journal entry',"(async()=>{closeSheet();await T.w(300);window.__la=JSON.stringify({addJournal:'1',fromWidget:'1'});const B=window.Bridge;window.Bridge=new Proxy(B,{get:(t,k)=>k==='getLaunchAction'?()=>{const v=window.__la;window.__la='';return v;}:t[k]});nat=window.Bridge;handleLaunchAction();await T.w(900);return T.ok(sheetOpen==='jrSheet'&&T.page()==='pgJr','sheet '+sheetOpen+' page '+T.page())})()"),
 ('NAT-06','Android','Several photos chosen at once are all added to the entry',"(async()=>{const c=document.createElement('canvas');c.width=40;c.height=30;const b=c.toDataURL('image/jpeg').split(',')[1];window.Bridge=new Proxy(window.Bridge,{get:(t,k)=>k==='readPhoto'?()=>b:k==='deletePhoto'?()=>{}:t[k]});nat=window.Bridge;openJr(null);"+W+"photoResultsMulti(['p1.jpg','p2.jpg','p3.jpg']);await T.w(2500);const n=jrEd.photos.length;closeSheet();return T.ok(n===3,n+' added')})()"),
